macro_rules! native {
    ($id:ident, $method:ident, $path:literal, $service:ident, $dialect:ident) => {
        super::ai_service(
            RouteId::$id,
            RouteMethod::$method,
            $path,
            ServiceKind::$service,
            ApiDialect::$dialect,
        )
    };
}
